import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5319,
    host: '0.0.0.0',
  },
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: #f3f4f6;
  color: #1f2937;
  padding: 24px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  background: white;
  padding: 24px;
  border-radius: 8px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

h1 {
  font-size: 24px;
  margin-top: 0;
  margin-bottom: 20px;
  color: #111827;
}

.controls {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.control-group label {
  font-size: 12px;
  font-weight: 600;
  color: #4b5563;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

select {
  padding: 8px 12px;
  border-radius: 6px;
  border: 1px solid #d1d5db;
  background-color: white;
  font-size: 14px;
  color: #374151;
  outline: none;
  cursor: pointer;
}

select:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.table-wrapper {
  overflow-x: auto;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  position: relative;
}

table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 14px;
  text-align: left;
}

th, td {
  padding: 12px 16px;
  border-bottom: 1px solid #e5e7eb;
  border-right: 1px solid #e5e7eb;
  white-space: nowrap;
}

th:last-child, td:last-child {
  border-right: none;
}

tr:last-child td {
  border-bottom: none;
}

thead {
  background-color: #f9fafb;
}

th {
  font-weight: 600;
  color: #374151;
}

/* Pinned column styling */
.pinned-col {
  position: sticky;
  left: 0;
  background-color: white;
  z-index: 1;
}

th.pinned-col {
  background-color: #f9fafb;
  z-index: 2;
}

/* Highlight group rows */
.group-row {
  background-color: #f3f4f6;
  font-weight: 600;
}

.group-row .pinned-col {
  background-color: #f3f4f6;
}

/* Footer styling */
tfoot {
  background-color: #f9fafb;
  font-weight: bold;
}

tfoot .pinned-col {
  background-color: #f9fafb;
}

button.toggle-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px 8px;
  margin-right: 8px;
  font-size: 12px;
  border-radius: 4px;
  color: #4b5563;
}

button.toggle-btn:hover {
  background-color: rgba(0, 0, 0, 0.05);
  color: #111827;
}

.badge {
  background-color: #e5e7eb;
  color: #4b5563;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 11px;
  margin-left: 8px;
  font-weight: normal;
}

import React, { useMemo, useState } from 'react';
import {
  useReactTable,
  getCoreRowModel,
  getGroupedRowModel,
  getExpandedRowModel,
  getSortedRowModel,
} from '@tanstack/react-table';

const DATA = [
  { region: 'North', category: 'Widgets', salesperson: 'Alice', amount: 1200, units: 40 },
  { region: 'North', category: 'Gadgets', salesperson: 'Alice', amount: 800, units: 20 },
  { region: 'North', category: 'Widgets', salesperson: 'Bob', amount: 600, units: 15 },
  { region: 'South', category: 'Widgets', salesperson: 'Carol', amount: 1500, units: 50 },
  { region: 'South', category: 'Gadgets', salesperson: 'Carol', amount: 400, units: 10 },
  { region: 'South', category: 'Gadgets', salesperson: 'Dave', amount: 900, units: 30 },
  { region: 'East', category: 'Widgets', salesperson: 'Erin', amount: 300, units: 10 },
  { region: 'East', category: 'Gadgets', salesperson: 'Erin', amount: 1100, units: 25 },
  { region: 'North', category: 'Gadgets', salesperson: 'Bob', amount: 700, units: 35 },
  { region: 'South', category: 'Widgets', salesperson: 'Dave', amount: 700, units: 28 },
  { region: 'East', category: 'Widgets', salesperson: 'Frank', amount: 2000, units: 80 },
  { region: 'East', category: 'Gadgets', salesperson: 'Frank', amount: 600, units: 15 },
];

export default function App() {
  const [groupBy, setGroupBy] = useState('none');
  const [grouping, setGrouping] = useState([]);
  const [expanded, setExpanded] = useState({});
  const [sortGroups, setSortGroups] = useState('none');
  const [sorting, setSorting] = useState([]);

  const columns = useMemo(
    () => [
      {
        accessorKey: 'region',
        id: 'region',
        header: 'Region',
      },
      {
        accessorKey: 'category',
        id: 'category',
        header: 'Category',
      },
      {
        accessorKey: 'salesperson',
        id: 'salesperson',
        header: 'Salesperson',
      },
      {
        accessorKey: 'amount',
        id: 'amount',
        header: 'Amount',
        aggregationFn: 'sum',
      },
      {
        accessorKey: 'units',
        id: 'units',
        header: 'Units',
        aggregationFn: 'sum',
      },
      {
        accessorKey: 'unitPrice',
        id: 'unitPrice',
        header: 'Unit Price',
        accessorFn: (row) => row.amount / row.units,
        aggregationFn: (columnId, leafRows) => {
          if (!leafRows.length) return 0;
          const sum = leafRows.reduce((acc, row) => {
            const amount = row.original.amount;
            const units = row.original.units;
            return acc + amount / units;
          }, 0);
          return sum / leafRows.length;
        },
      },
    ],
    []
  );

  const table = useReactTable({
    data: DATA,
    columns,
    state: {
      grouping,
      expanded,
      sorting,
    },
    onGroupingChange: setGrouping,
    onExpandedChange: setExpanded,
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getGroupedRowModel: getGroupedRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    getSortedRowModel: getSortedRowModel(),
  });

  const handleGroupByChange = (e) => {
    const val = e.target.value;
    setGroupBy(val);
    if (val === 'none') {
      setGrouping([]);
    } else {
      setGrouping([val]);
    }
    setExpanded({});
  };

  const handleSortGroupsChange = (e) => {
    const val = e.target.value;
    setSortGroups(val);
    if (val === 'none') {
      setSorting([]);
    } else if (val === 'asc') {
      setSorting([{ id: 'amount', desc: false }]);
    } else if (val === 'desc') {
      setSorting([{ id: 'amount', desc: true }]);
    }
  };

  // Grand total is always the sum of amount over the whole dataset
  const grandTotalAmount = useMemo(() => {
    return DATA.reduce((sum, row) => sum + row.amount, 0);
  }, []);

  return (
    <div className="container">
      <h1>Analytical Sales Data Table</h1>

      <div className="controls">
        <div className="control-group">
          <label htmlFor="group-by">Group By</label>
          <select
            id="group-by"
            data-testid="group-by"
            value={groupBy}
            onChange={handleGroupByChange}
          >
            <option value="none">none</option>
            <option value="region">region</option>
            <option value="category">category</option>
          </select>
        </div>

        <div className="control-group">
          <label htmlFor="sort-groups">Sort Groups (by Amount)</label>
          <select
            id="sort-groups"
            data-testid="sort-groups"
            value={sortGroups}
            onChange={handleSortGroupsChange}
          >
            <option value="none">none</option>
            <option value="asc">asc</option>
            <option value="desc">desc</option>
          </select>
        </div>
      </div>

      <div className="table-wrapper">
        <table>
          <thead>
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header, index) => {
                  const isFirstCol = index === 0;
                  return (
                    <th
                      key={header.id}
                      data-testid={isFirstCol ? 'pinned-col-header' : undefined}
                      className={isFirstCol ? 'pinned-col' : ''}
                      style={
                        isFirstCol
                          ? {
                              position: 'sticky',
                              left: '0px',
                              zIndex: 10,
                            }
                          : undefined
                      }
                    >
                      {header.isPlaceholder
                        ? null
                        : typeof header.column.columnDef.header === 'function'
                        ? header.column.columnDef.header(header.getContext())
                        : header.column.columnDef.header}
                    </th>
                  );
                })}
              </tr>
            ))}
          </thead>
          <tbody>
            {table.getRowModel().rows.map((row) => {
              if (row.getIsGrouped()) {
                // Group header row
                const sumAmount = row.leafRows.reduce(
                  (sum, r) => sum + r.original.amount,
                  0
                );
                const sumUnitPrice = row.leafRows.reduce(
                  (sum, r) => sum + r.original.amount / r.original.units,
                  0
                );
                const avgUnitPrice = sumUnitPrice / row.leafRows.length;
                const count = row.leafRows.length;

                return (
                  <tr
                    key={row.id}
                    data-testid="group-row"
                    data-group-value={row.groupingValue}
                    className="group-row"
                  >
                    {/* First column: Pinned, containing toggle, value and count */}
                    <td
                      className="pinned-col"
                      style={{
                        position: 'sticky',
                        left: '0px',
                        zIndex: 2,
                      }}
                    >
                      <button
                        data-testid="group-toggle"
                        className="toggle-btn"
                        onClick={row.getToggleExpandedHandler()}
                      >
                        {row.getIsExpanded() ? '▼' : '▶'}
                      </button>
                      <span>{row.groupingValue}</span>
                      <span className="badge" data-testid="group-count">
                        {count}
                      </span>
                    </td>
                    <td></td>
                    <td></td>
                    <td>
                      <span data-testid="group-sum-amount">{sumAmount}</span>
                    </td>
                    <td></td>
                    <td>
                      <span data-testid="group-avg-unit-price">
                        {avgUnitPrice}
                      </span>
                    </td>
                  </tr>
                );
              } else {
                // Leaf data row
                const isGroupedActive = groupBy !== 'none';
                const groupValue = isGroupedActive
                  ? row.original[groupBy]
                  : undefined;

                return (
                  <tr
                    key={row.id}
                    data-testid="data-row"
                    data-group-value={groupValue}
                  >
                    {/* First column: Region (pinned) */}
                    <td
                      className="pinned-col"
                      style={{
                        position: 'sticky',
                        left: '0px',
                        zIndex: 1,
                      }}
                    >
                      {row.original.region}
                    </td>
                    <td>{row.original.category}</td>
                    <td>{row.original.salesperson}</td>
                    <td data-testid="cell-amount">{row.original.amount}</td>
                    <td>{row.original.units}</td>
                    <td>{row.original.amount / row.original.units}</td>
                  </tr>
                );
              }
            })}
          </tbody>
          <tfoot>
            <tr>
              <td
                className="pinned-col"
                style={{
                  position: 'sticky',
                  left: '0px',
                  zIndex: 3,
                  fontWeight: 'bold',
                }}
              >
                Grand Total
              </td>
              <td></td>
              <td></td>
              <td data-testid="grand-total-amount" style={{ fontWeight: 'bold' }}>
                {grandTotalAmount}
              </td>
              <td></td>
              <td></td>
            </tr>
          </footer>
        </table>
      </div>
    </div>
  );
}

import { chromium } from 'playwright';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Navigating to http://localhost:5319/...');
    await page.goto('http://localhost:5319/');

    // 1. Initial State: No Grouping
    console.log('Testing initial state (no grouping)...');

    // Check group-by select
    const groupBySelect = await page.locator('[data-testid="group-by"]');
    await groupBySelect.waitFor({ state: 'visible' });
    const groupByVal = await groupBySelect.inputValue();
    if (groupByVal !== 'none') {
      throw new Error(`Expected group-by to be "none", got "${groupByVal}"`);
    }

    // Check sort-groups select
    const sortSelect = await page.locator('[data-testid="sort-groups"]');
    const sortVal = await sortSelect.inputValue();
    if (sortVal !== 'none') {
      throw new Error(`Expected sort-groups to be "none", got "${sortVal}"`);
    }

    // Check data rows (should be 12)
    const dataRows = await page.locator('[data-testid="data-row"]');
    const rowCount = await dataRows.count();
    if (rowCount !== 12) {
      throw new Error(`Expected 12 data rows, got ${rowCount}`);
    }
    console.log('✓ Initial state is correct. 12 data rows visible.');

    // Check Grand Total
    const grandTotal = await page.locator('[data-testid="grand-total-amount"]').textContent();
    if (grandTotal.trim() !== '10800') {
      throw new Error(`Expected grand total to be "10800", got "${grandTotal}"`);
    }
    console.log(`✓ Grand total is correct: ${grandTotal}`);

    // Check Pinned Column Header
    const pinnedHeader = await page.locator('[data-testid="pinned-col-header"]');
    const stickyStyle = await pinnedHeader.evaluate(el => window.getComputedStyle(el).position);
    const leftStyle = await pinnedHeader.evaluate(el => window.getComputedStyle(el).left);
    if (stickyStyle !== 'sticky' || leftStyle !== '0px') {
      throw new Error(`Expected pinned-col-header to be sticky at 0px, got position: ${stickyStyle}, left: ${leftStyle}`);
    }
    console.log('✓ Pinned column header is sticky at 0px.');

    // 2. Group by region
    console.log('Setting grouping to "region"...');
    await groupBySelect.selectOption('region');
    await page.waitForTimeout(500);

    // Group header rows should be visible (3 groups: North, South, East)
    const groupRows = await page.locator('[data-testid="group-row"]');
    const groupRowsCount = await groupRows.count();
    if (groupRowsCount !== 3) {
      throw new Error(`Expected 3 group rows, got ${groupRowsCount}`);
    }

    // Data rows should be hidden because groups start collapsed
    const visibleDataRowsCount = await page.locator('[data-testid="data-row"]').count();
    if (visibleDataRowsCount !== 0) {
      throw new Error(`Expected 0 data rows visible when groups are collapsed, got ${visibleDataRowsCount}`);
    }
    console.log('✓ Grouping by region applied. 3 group rows visible, 0 data rows visible (collapsed).');

    // Check values in the group header rows
    const northRow = page.locator('[data-testid="group-row"][data-group-value="North"]');
    const northSum = await northRow.locator('[data-testid="group-sum-amount"]').textContent();
    const northAvg = await northRow.locator('[data-testid="group-avg-unit-price"]').textContent();
    const northCount = await northRow.locator('[data-testid="group-count"]').textContent();

    if (northSum.trim() !== '3300') {
      throw new Error(`Expected North sum to be "3300", got "${northSum}"`);
    }
    if (parseFloat(northAvg.trim()) !== 32.5) {
      throw new Error(`Expected North avg unit price to be "32.5", got "${northAvg}"`);
    }
    if (northCount.trim() !== '4') {
      throw new Error(`Expected North count to be "4", got "${northCount}"`);
    }
    console.log('✓ North group aggregates are correct.');

    // 3. Test expansion
    console.log('Expanding North group...');
    const northToggle = northRow.locator('[data-testid="group-toggle"]');
    await northToggle.click();
    await page.waitForTimeout(500);

    // Now, there should be 4 visible data rows under North group
    const expandedDataRows = page.locator('[data-testid="data-row"]');
    const expandedCount = await expandedDataRows.count();
    if (expandedCount !== 4) {
      throw new Error(`Expected 4 data rows to be visible after expanding North, got ${expandedCount}`);
    }

    // Verify they are indeed under North
    for (let i = 0; i < expandedCount; i++) {
      const gVal = await expandedDataRows.nth(i).getAttribute('data-group-value');
      if (gVal !== 'North') {
        throw new Error(`Expected data-group-value of visible rows to be "North", got "${gVal}"`);
      }
    }
    console.log('✓ North group expanded. 4 data rows visible under North.');

    // Collapse North group again
    console.log('Collapsing North group...');
    await northToggle.click();
    await page.waitForTimeout(500);
    const collapsedCount = await page.locator('[data-testid="data-row"]').count();
    if (collapsedCount !== 0) {
      throw new Error(`Expected 0 data rows visible after collapsing North, got ${collapsedCount}`);
    }
    console.log('✓ North group collapsed successfully.');

    // 4. Test group sorting
    console.log('Testing group sorting by amount...');
    // Default order should be North (3300), South (3500), East (4000)
    let currentOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Default group order:', currentOrder);

    // Sort descending: East (4000), South (3500), North (3300)
    console.log('Sorting desc...');
    await sortSelect.selectOption('desc');
    await page.waitForTimeout(500);
    let descOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Desc group order:', descOrder);
    if (descOrder[0] !== 'East' || descOrder[1] !== 'South' || descOrder[2] !== 'North') {
      throw new Error(`Unexpected group order for desc: ${JSON.stringify(descOrder)}`);
    }
    console.log('✓ Descending sorting is correct.');

    // Sort ascending: North (3300), South (3500), East (4000)
    console.log('Sorting asc...');
    await sortSelect.selectOption('asc');
    await page.waitForTimeout(500);
    let ascOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Asc group order:', ascOrder);
    if (ascOrder[0] !== 'North' || ascOrder[1] !== 'South' || ascOrder[2] !== 'East') {
      throw new Error(`Unexpected group order for asc: ${JSON.stringify(ascOrder)}`);
    }
    console.log('✓ Ascending sorting is correct.');

    console.log('ALL TESTS PASSED SUCCESSFULLY!');
  } catch (err) {
    console.error('TEST FAILED:', err);
    process.exit(1);
  } finally {
    await browser.close();
  }
})();

