    // Collapse North group again
    console.log('Collapsing North group...');
    await northToggle.click();
    await page.waitForTimeout(500);
    const collapsedCount = await page.locator('[data-testid="data-row"]').count();
    if (collapsedCount !== 0) {
      throw new Error(`Expected 0 data rows visible after collapsing North, got ${collapsedCount}`);
    }
    console.log('✓ North group collapsed successfully.');

    // 4. Test group sorting for region
    console.log('Testing region group sorting by amount...');
    // Default order should be North (3300), South (3500), East (4000)
    let currentOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Default group order:', currentOrder);

    // Sort descending: East (4000), South (3500), North (3300)
    console.log('Sorting desc...');
    await sortSelect.selectOption('desc');
    await page.waitForTimeout(500);
    let descOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Desc group order:', descOrder);
    if (descOrder[0] !== 'East' || descOrder[1] !== 'South' || descOrder[2] !== 'North') {
      throw new Error(`Unexpected group order for desc: ${JSON.stringify(descOrder)}`);
    }
    console.log('✓ Descending sorting for region is correct.');

    // Sort ascending: North (3300), South (3500), East (4000)
    console.log('Sorting asc...');
    await sortSelect.selectOption('asc');
    await page.waitForTimeout(500);
    let ascOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Asc group order:', ascOrder);
    if (ascOrder[0] !== 'North' || ascOrder[1] !== 'South' || ascOrder[2] !== 'East') {
      throw new Error(`Unexpected group order for asc: ${JSON.stringify(ascOrder)}`);
    }
    console.log('✓ Ascending sorting for region is correct.');

    // Reset sort-groups to none
    await sortSelect.selectOption('none');
    await page.waitForTimeout(500);

    // 5. Group by category
    console.log('Setting grouping to "category"...');
    await groupBySelect.selectOption('category');
    await page.waitForTimeout(500);

    // Group header rows should be visible (2 groups: Widgets, Gadgets)
    const catGroupRows = await page.locator('[data-testid="group-row"]');
    const catGroupRowsCount = await catGroupRows.count();
    if (catGroupRowsCount !== 2) {
      throw new Error(`Expected 2 group rows, got ${catGroupRowsCount}`);
    }

    // Data rows should be hidden because groups start collapsed
    const catVisibleDataRowsCount = await page.locator('[data-testid="data-row"]').count();
    if (catVisibleDataRowsCount !== 0) {
      throw new Error(`Expected 0 data rows visible when groups are collapsed, got ${catVisibleDataRowsCount}`);
    }
    console.log('✓ Grouping by category applied. 2 group rows visible, 0 data rows visible (collapsed).');

    // Check values in the group header rows
    const widgetsRow = page.locator('[data-testid="group-row"][data-group-value="Widgets"]');
    const widgetsSum = await widgetsRow.locator('[data-testid="group-sum-amount"]').textContent();
    const widgetsAvg = await widgetsRow.locator('[data-testid="group-avg-unit-price"]').textContent();
    const widgetsCount = await widgetsRow.locator('[data-testid="group-count"]').textContent();

    if (widgetsSum.trim() !== '6300') {
      throw new Error(`Expected Widgets sum to be "6300", got "${widgetsSum}"`);
    }
    if (parseFloat(widgetsAvg.trim()) !== 30) {
      throw new Error(`Expected Widgets avg unit price to be "30", got "${widgetsAvg}"`);
    }
    if (widgetsCount.trim() !== '6') {
      throw new Error(`Expected Widgets count to be "6", got "${widgetsCount}"`);
    }
    console.log('✓ Widgets group aggregates are correct.');

    const gadgetsRow = page.locator('[data-testid="group-row"][data-group-value="Gadgets"]');
    const gadgetsSum = await gadgetsRow.locator('[data-testid="group-sum-amount"]').textContent();
    const gadgetsAvg = await gadgetsRow.locator('[data-testid="group-avg-unit-price"]').textContent();
    const gadgetsCount = await gadgetsRow.locator('[data-testid="group-count"]').textContent();

    if (gadgetsSum.trim() !== '4500') {
      throw new Error(`Expected Gadgets sum to be "4500", got "${gadgetsSum}"`);
    }
    // Gadgets unit prices: (40 + 40 + 30 + 44 + 20 + 40) / 6 = 214 / 6 = 35.666666666666664
    const parsedGadgetsAvg = parseFloat(gadgetsAvg.trim());
    if (Math.abs(parsedGadgetsAvg - 35.666666666666664) > 0.0001) {
      throw new Error(`Expected Gadgets avg unit price to be around "35.6667", got "${gadgetsAvg}"`);
    }
    if (gadgetsCount.trim() !== '6') {
      throw new Error(`Expected Gadgets count to be "6", got "${gadgetsCount}"`);
    }
    console.log('✓ Gadgets group aggregates are correct.');

    // 6. Test category group sorting
    console.log('Testing category group sorting by amount...');
    // Default order should be Widgets (6300), Gadgets (4500)
    let catCurrentOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Default category group order:', catCurrentOrder);

    // Sort descending: Widgets (6300), Gadgets (4500)
    console.log('Sorting desc...');
    await sortSelect.selectOption('desc');
    await page.waitForTimeout(500);
    let catDescOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Desc category group order:', catDescOrder);
    if (catDescOrder[0] !== 'Widgets' || catDescOrder[1] !== 'Gadgets') {
      throw new Error(`Unexpected category group order for desc: ${JSON.stringify(catDescOrder)}`);
    }
    console.log('✓ Descending sorting for category is correct.');

    // Sort ascending: Gadgets (4500), Widgets (6300)
    console.log('Sorting asc...');
    await sortSelect.selectOption('asc');
    await page.waitForTimeout(500);
    let catAscOrder = await page.locator('[data-testid="group-row"]').evaluateAll(els => 
      els.map(el => el.getAttribute('data-group-value'))
    );
    console.log('Asc category group order:', catAscOrder);
    if (catAscOrder[0] !== 'Gadgets' || catAscOrder[1] !== 'Widgets') {
      throw new Error(`Unexpected category group order for asc: ${JSON.stringify(catAscOrder)}`);
    }
    console.log('✓ Ascending sorting for category is correct.');

    console.log('ALL TESTS PASSED SUCCESSFULLY!');
  } catch (err) {
    console.error('TEST FAILED:', err);
    process.exit(1);
  } finally {
    await browser.close();
  }
})();
